type CircuitBreaker struct {
    failures  int
    threshold int
    open      bool
}

func (cb *CircuitBreaker) Call(fn func() error) error {
    if cb.open {
        return errors.New("circuit open")
    }
    err := fn()
    if err != nil {
        cb.failures++
        if cb.failures >= cb.threshold {
            cb.open = true
        }
    }
    return err
}

